static void Bolse_StationHullFacet(s32 side, f32 height, f32 width, s32 r, s32 g, s32 b) {
    f32 angle = (side + 0.5f) * (360.0f / BOLSE_INTERIOR_SIDES);
    f32 middle = (BOLSE_INTERIOR_FRONT + BOLSE_INTERIOR_BACK) * 0.5f;
    if (side % 2 != 0) {
        Bolse_StationPanel(angle, 0, height, middle, width, BOLSE_INTERIOR_LENGTH * 0.5f, r, g, b);
        return;
    }
    f32 pitch = BOLSE_INTERIOR_LENGTH / BOLSE_INTERIOR_GARDEN_ROWS;
    f32 bedWidth = BOLSE_INTERIOR_RADIUS * SIN_DEG(180.0f / BOLSE_INTERIOR_SIDES) * 0.76f;
    f32 bedLength = pitch * 0.36f;
    /* Cut beds out of the hull so a distant green plane has no competing surface behind it. */
    for (s32 row = 0; row < BOLSE_INTERIOR_GARDEN_ROWS; row++) {
        f32 z = BOLSE_INTERIOR_FRONT - (row + 0.5f) * pitch;
        for (s32 edge = -1; edge <= 1; edge += 2) {
            Bolse_StationPanel(angle, edge * (width + bedWidth) * 0.5f, height, z,
                              (width - bedWidth) * 0.5f, pitch * 0.5f, r, g, b);
            Bolse_StationPanel(angle, 0, height, z + edge * (pitch * 0.5f + bedLength) * 0.5f,
                              bedWidth, (pitch * 0.5f - bedLength) * 0.5f, r, g, b);
        }
    }
}

static void Bolse_StationBuild(void) {
    sStationVertexCount = sStationCommandCount = sStationObstacleCount = sStationTreeCount = 0;
    memset(sStationTerrain,0,sizeof(sStationTerrain));
    const f32 front = BOLSE_INTERIOR_FRONT, back = BOLSE_INTERIOR_BACK;
    for (s32 side = 0; side < BOLSE_INTERIOR_SIDES; side++) {
        f32 angle = side * (360.0f / BOLSE_INTERIOR_SIDES);
        f32 next = angle + 360.0f / BOLSE_INTERIOR_SIDES;
        Vec3f a = Bolse_StationPoint(angle, 0, 0, front);
        Vec3f b = Bolse_StationPoint(next, 0, 0, front);
        f32 halfWidth = BOLSE_INTERIOR_RADIUS * SIN_DEG(180.0f / BOLSE_INTERIOR_SIDES);
        f32 apothem = BOLSE_INTERIOR_RADIUS * COS_DEG(180.0f / BOLSE_INTERIOR_SIDES);
        Bolse_StationHullFacet(side, BOLSE_INTERIOR_RADIUS - apothem, halfWidth,
                               67 + side % 3 * 5, 82 + side % 3 * 5, 91 + side % 3 * 5);
        Bolse_StationHullFacet(side, BOLSE_INTERIOR_RADIUS - apothem * 1.035f,
                               halfWidth * 1.035f, 31, 41, 53);
        /* The exterior bulkhead is slightly larger, open only at the entry. */
        a.x *= 1.035f; a.y *= 1.035f; b.x *= 1.035f; b.y *= 1.035f;
        Vec3f innerA = { a.x * 0.15f, a.y * 0.15f, front };
        Vec3f innerB = { b.x * 0.15f, b.y * 0.15f, front };
        /* Rectangular opening matches the scaled Andross tunnel's throat. */
        f32 da = fmaxf(fabsf(innerA.x) / BOLSE_INTERIOR_ENTRY_HALF_WIDTH,
                        fabsf(innerA.y) / BOLSE_INTERIOR_ENTRY_HALF_HEIGHT);
        f32 db = fmaxf(fabsf(innerB.x) / BOLSE_INTERIOR_ENTRY_HALF_WIDTH,
                        fabsf(innerB.y) / BOLSE_INTERIOR_ENTRY_HALF_HEIGHT);
        innerA.x /= da; innerA.y /= da; innerB.x /= db; innerB.y /= db;
        Bolse_StationQuad(a, b, innerB, innerA, 83 + side % 2 * 7, 101, 116);
        a.z = b.z = back;
        Bolse_StationTriangle(a, b, (Vec3f) { 0, 0, back }, 6, 10, 17);
        for (s32 ring = 1; ring <= 3; ring++) {
            f32 radius = BOLSE_INTERIOR_RADIUS * ring * 0.26f;
            f32 inset = 24;
            f32 sn = SIN_DEG(angle), cs = COS_DEG(angle);
            f32 ns = SIN_DEG(next), nc = COS_DEG(next);
            Bolse_StationQuad((Vec3f) { sn*radius, -cs*radius, back+3 },
                (Vec3f) { ns*radius, -nc*radius, back+3 },
                (Vec3f) { ns*(radius-inset), -nc*(radius-inset), back+3 },
                (Vec3f) { sn*(radius-inset), -cs*(radius-inset), back+3 }, 21, 30, 43);
        }

        f32 middle = angle + 180.0f / BOLSE_INTERIOR_SIDES;
        f32 halfFacet = BOLSE_INTERIOR_RADIUS * SIN_DEG(180.0f / BOLSE_INTERIOR_SIDES);
        f32 inset = BOLSE_INTERIOR_RADIUS * (1 - COS_DEG(180.0f / BOLSE_INTERIOR_SIDES));
        f32 rowPitch = BOLSE_INTERIOR_LENGTH / BOLSE_INTERIOR_GARDEN_ROWS;
        f32 gardenWidth = halfFacet * 0.76f, gardenLength = rowPitch * 0.36f;
        for (s32 row = 0; row < BOLSE_INTERIOR_GARDEN_ROWS; row++) {
            f32 z = front - (row + 0.5f) * rowPitch;
            if (side % 2 == 0) {
                /* Separate rectangular trays, bounded on all four sides, with clear service aisles. */
                Bolse_StationGardenTray(middle, z, gardenWidth, gardenLength, inset);
                Bolse_StationTerrainPanel(0, middle, 0, inset + 73, z, gardenWidth, gardenLength);
                Bolse_StationPanel(middle, -gardenWidth - 12, inset + 72, z, 12, gardenLength + 24, 115, 135, 134);
                Bolse_StationPanel(middle, gardenWidth + 12, inset + 72, z, 12, gardenLength + 24, 115, 135, 134);
                Bolse_StationPanel(middle, 0, inset + 72, z - gardenLength - 12, gardenWidth + 24, 12, 115, 135, 134);
                Bolse_StationPanel(middle, 0, inset + 72, z + gardenLength + 12, gardenWidth + 24, 12, 115, 135, 134);
                Bolse_StationTerrainPanel(1, middle, 0, inset + 35, z + gardenLength + 130, gardenWidth + 100, 66);
                if (side % 2 == 0) {
                    Bolse_StationTree(middle, -gardenWidth * 0.45f, z - gardenLength * 0.33f, side + row);
                    Bolse_StationTree(middle, gardenWidth * 0.45f, z + gardenLength * 0.33f, side + row + 1);
                }
            } else {
                /* Recessed Corneria metal plates break up the bare service decks. */
                Bolse_StationTerrainPanel(2, middle, 0, inset + 12, z, halfFacet * 0.86f, rowPitch * 0.43f);
            }
            if (side % 4 == 3 && row % 2 == 0) {
                Bolse_StationBox(middle, 0, inset + 130, z, 500, 130, 530, 130, 144, 153, true);
                Bolse_StationPanel(middle, 0, inset + 265, z, 440, 470, 181, 126, 58);
                Bolse_StationPanel(middle, -420, inset + 268, z, 15, 440, 254, 217, 138);
                Bolse_StationPanel(middle, 420, inset + 268, z, 15, 440, 254, 217, 138);
                Bolse_StationBox(middle, 0, inset + 440, z - 660, 440, 440, 110, 113, 137, 157, true);
                for (s32 window = -3; window <= 3; window++) {
                    Bolse_StationBox(middle, window * 110, inset + 590, z - 543, 30, 100, 4, 132, 225, 239, false);
                }
            }
        }
        /* Lights and ring braces run along the aisles instead of crossing the grass. */
        Bolse_StationPanel(middle, halfFacet * 0.98f, inset + 170, (front + back) * 0.5f,
                          16, BOLSE_INTERIOR_LENGTH * 0.5f - 100, 194, 244, 231);
        for (s32 ring = 0; ring <= BOLSE_INTERIOR_GARDEN_ROWS; ring++) {
            f32 z = front - ring * rowPitch;
            Bolse_StationBox(middle, 0, inset + 50, z, halfFacet, 95, 55, 132, 153, 164, false);
            Bolse_StationPanel(middle, 0, inset + 150, z, halfFacet * 0.8f, 12, 190, 228, 230);
        }
    }
    /* Connected polygon walkways let both robots traverse the habitat walls and ceiling. */
    for (s32 lane = 0; lane < 2; lane++) {
        f32 inset = BOLSE_INTERIOR_RADIUS*(1-COS_DEG(180.0f/BOLSE_INTERIOR_SIDES));
        f32 width = (BOLSE_INTERIOR_RADIUS-inset-850)*tanf(180.0f/BOLSE_INTERIOR_SIDES*M_DTOR);
        for (s32 side = 0; side < BOLSE_INTERIOR_SIDES; side++) {
            f32 angle = (side+0.5f)*(360.0f/BOLSE_INTERIOR_SIDES);
            Bolse_StationBox(angle,0,inset+780,sStationRobotZ[lane],width,70,1500,100,119,128,true);
            Bolse_StationPanel(angle,0,inset+855,sStationRobotZ[lane],width,1380,118,132,137);
        }
    }
    Bolse_StationBuildDockingArea();
    /* Approach rails lead the eye to the original Venom entrance. */
    for (s32 side = -1; side <= 1; side += 2) {
        Bolse_StationQuad((Vec3f) {side*1500, -1320, 11900}, (Vec3f) {side*1450, -1320, 11900},
                         (Vec3f) {side*760, -680, 9600}, (Vec3f) {side*810, -680, 9600}, 102, 230, 207);
    }
    Bolse_StationQuad((Vec3f){-BOLSE_INTERIOR_ENTRY_HALF_WIDTH,-BOLSE_INTERIOR_ENTRY_HALF_HEIGHT,BOLSE_INTERIOR_FRONT-16},(Vec3f){BOLSE_INTERIOR_ENTRY_HALF_WIDTH,-BOLSE_INTERIOR_ENTRY_HALF_HEIGHT,BOLSE_INTERIOR_FRONT-16},(Vec3f){BOLSE_INTERIOR_ENTRY_HALF_WIDTH,BOLSE_INTERIOR_ENTRY_HALF_HEIGHT,BOLSE_INTERIOR_FRONT-16},(Vec3f){-BOLSE_INTERIOR_ENTRY_HALF_WIDTH,BOLSE_INTERIOR_ENTRY_HALF_HEIGHT,BOLSE_INTERIOR_FRONT-16},30,90,150);
    Bolse_StationBakeLighting();
    for (s32 i=0;i<ARRAY_COUNT(sStationTerrain);i++) gSPEndDisplayList(&sStationTerrain[i].commands[sStationTerrain[i].commandCount]);
    gSPEndDisplayList(&sStationMesh[sStationCommandCount++]);
    Bolse_StationBuildDockingGuides();
    sStationReady = true;
}

static bool Bolse_StationClamp(f32* value, f32 low, f32 high) {
    f32 old = *value;
    if (*value < low) *value = low;
    if (*value > high) *value = high;
    return *value != old;
}

static void Bolse_StationAperture(f32 z, f32* width, f32* height) {
    f32 flare = fmaxf(0, fminf(1, (z - BOLSE_INTERIOR_ENTRY_THROAT) / (BOLSE_INTERIOR_ENTRY_MOUTH - BOLSE_INTERIOR_ENTRY_THROAT)));
    *width = BOLSE_INTERIOR_ENTRY_HALF_WIDTH + flare * (641 * BOLSE_INTERIOR_ENTRY_SCALE - BOLSE_INTERIOR_ENTRY_HALF_WIDTH);
    *height = BOLSE_INTERIOR_ENTRY_HALF_HEIGHT + flare * (520 * BOLSE_INTERIOR_ENTRY_SCALE - BOLSE_INTERIOR_ENTRY_HALF_HEIGHT);
}

static bool Bolse_StationResolve(Vec3f* pos, Vec3f previous, f32 gap) {
    bool hit = false;
    /* Crossing either bulkhead is legal only through its opening. */
    const f32 planes[2] = { BOLSE_INTERIOR_FRONT, BOLSE_INTERIOR_ENTRY_MOUTH };
    for (s32 i = 0; i < 2; i++) {
        f32 plane = planes[i], width, height;
        Bolse_StationAperture(plane, &width, &height);
        if ((pos->z - plane) * (previous.z - plane) <= 0 && pos->z != previous.z) {
            f32 t = (plane - previous.z) / (pos->z - previous.z);
            f32 x = previous.x + (pos->x - previous.x) * t;
            f32 y = previous.y + (pos->y - previous.y) * t;
            if (fabsf(x) > width - gap || fabsf(y) > height - gap) {
                pos->z = plane + (previous.z > plane ? gap : -gap);
                hit = true;
            }
        }
    }
    if (pos->z > BOLSE_INTERIOR_ENTRY_MOUTH) {
        hit |= Bolse_StationClamp(&pos->z, BOLSE_INTERIOR_ENTRY_MOUTH, 14500);
        f32 radial = sqrtf(SQ(pos->x) + SQ(pos->y));
        if (radial > 6500) {
            pos->x *= 6500 / radial; pos->y *= 6500 / radial; hit = true;
        }
    } else if (pos->z > BOLSE_INTERIOR_FRONT) {
        f32 width, height;
        Bolse_StationAperture(pos->z, &width, &height);
        hit |= Bolse_StationClamp(&pos->x, -width + gap, width - gap);
        hit |= Bolse_StationClamp(&pos->y, -height + gap, height - gap);
    } else {
        hit |= Bolse_StationClamp(&pos->z, BOLSE_INTERIOR_BACK + gap, BOLSE_INTERIOR_FRONT);
        /* Half-spaces follow the rendered facets, including floor and ceiling. */
        f32 apothem = BOLSE_INTERIOR_RADIUS * COS_DEG(180.0f / BOLSE_INTERIOR_SIDES) - gap - 150;
        for (s32 side = 0; side < BOLSE_INTERIOR_SIDES; side++) {
            f32 angle = (side + 0.5f) * (360.0f / BOLSE_INTERIOR_SIDES);
            f32 nx = SIN_DEG(angle), ny = -COS_DEG(angle);
            f32 excess = pos->x * nx + pos->y * ny - apothem;
            if (excess > 0) {
                pos->x -= nx * excess; pos->y -= ny * excess; hit = true;
            }
        }
        for (s32 i = 0; i < sStationObstacleCount; i++) {
            BolseStationObstacle* obstacle = &sStationObstacles[i];
            f32 dx = pos->x - obstacle->pos.x, dy = pos->y - obstacle->pos.y;
            f32 dz = pos->z - obstacle->pos.z;
            if (obstacle->tree) {
                f32 radius = obstacle->half.x + gap;
                f32 distance = sqrtf(SQ(dx) + SQ(dy) + SQ(dz));
                if (distance < radius) {
                    if (distance < 0.01f) { dx = 0; dy = 1; dz = 0; distance = 1; }
                    f32 scale = radius / distance;
                    pos->x = obstacle->pos.x + dx * scale;
                    pos->y = obstacle->pos.y + dy * scale;
                    pos->z = obstacle->pos.z + dz * scale;
                    hit = true;
                }
            } else {
                f32 sn = SIN_DEG(obstacle->angle), cs = COS_DEG(obstacle->angle);
                f32 u = dx * cs + dy * sn, v = -dx * sn + dy * cs;
                f32 du = obstacle->half.x + gap - fabsf(u);
                f32 dv = obstacle->half.y + gap - fabsf(v);
                f32 dw = obstacle->half.z + gap - fabsf(dz);
                if (du > 0 && dv > 0 && dw > 0) {
                    if (du < dv && du < dw) {
                        f32 shift = (u < 0 ? -du : du);
                        pos->x += cs * shift; pos->y += sn * shift;
                    } else if (dv < dw) {
                        f32 shift = (v < 0 ? -dv : dv);
                        pos->x -= sn * shift; pos->y += cs * shift;
                    } else {
                        pos->z += (dz < 0 ? -dw : dw);
                    }
                    hit = true;
                }
            }
        }
    }
    return hit;
}

void BolseInterior_Draw(void) {
    if (!sStationReady) return;
    FrameInterpolation_RecordOpenChild(sStationMesh, 0);
    Matrix_Push(&gGfxMatrix);
    Matrix_SetGfxMtx(&gMasterDisp);
    RCP_SetupDL(&gMasterDisp, SETUPDL_29);
    gDPPipeSync(gMasterDisp++);
    gSPClearGeometryMode(gMasterDisp++, G_LIGHTING | G_CULL_BACK);
    gSPSetGeometryMode(gMasterDisp++, G_ZBUFFER | G_SHADE | G_SHADING_SMOOTH | G_FOG);
    gDPSetFogColor(gMasterDisp++,gFogRed,gFogGreen,gFogBlue,255);
    gSPFogPosition(gMasterDisp++,gFogNear,gFogFar);
    gSPTexture(gMasterDisp++, 0, 0, 0, G_TX_RENDERTILE, G_OFF);
    gDPSetCycleType(gMasterDisp++, G_CYC_2CYCLE);
    gDPSetCombineMode(gMasterDisp++, G_CC_SHADE, G_CC_PASS2);
    gDPSetRenderMode(gMasterDisp++, G_RM_FOG_SHADE_A, G_RM_AA_ZB_OPA_SURF2);
    gSPDisplayList(gMasterDisp++, sStationMesh);
    Bolse_StationDrawDockingPorts();
    for (s32 kind=0;kind<ARRAY_COUNT(sStationTerrain);kind++) {
        RCP_SetupDL(&gMasterDisp,SETUPDL_29);
        gSPClearGeometryMode(gMasterDisp++,G_LIGHTING|G_CULL_BACK);
        gSPSetGeometryMode(gMasterDisp++,G_FOG|G_SHADE|G_SHADING_SMOOTH|G_ZBUFFER);
        gDPSetFogColor(gMasterDisp++,gFogRed,gFogGreen,gFogBlue,255);
        gSPFogPosition(gMasterDisp++,gFogNear,gFogFar);
        gDPSetCycleType(gMasterDisp++,G_CYC_2CYCLE);
        gDPSetRenderMode(gMasterDisp++,G_RM_FOG_SHADE_A,G_RM_AA_ZB_OPA_SURF2);
        gSPTexture(gMasterDisp++,0xFFFF,0xFFFF,0,G_TX_RENDERTILE,G_ON);
        gDPSetTextureFilter(gMasterDisp++,G_TF_BILERP);
        if (kind==0) {
            /* Fade detail into its average green before it becomes subpixel noise.
             * One opaque surface keeps both the depth and fog continuous through the fade. */
            gDPSetEnvColor(gMasterDisp++,32,54,2,255);
            gDPSetCombineLERP(gMasterDisp++,TEXEL0,ENVIRONMENT,PRIM_LOD_FRAC,ENVIRONMENT,
                             0,0,0,SHADE,COMBINED,0,SHADE,0,0,0,0,COMBINED);
        } else {
            gDPSetCombineMode(gMasterDisp++,G_CC_MODULATEIA,G_CC_PASS2);
        }
        const char* texture = kind==0 ? D_CO_601C1A8 : (kind==1 ? D_CO_6028260 : D_CO_6010F90);
        gDPLoadTextureBlock(gMasterDisp++,texture,G_IM_FMT_RGBA,G_IM_SIZ_16b,
                           32,32,0,G_TX_WRAP,G_TX_WRAP,5,5,G_TX_NOLOD,G_TX_NOLOD);
        StationTerrain* terrain=&sStationTerrain[kind];
        Vec3f eye=gPlayer[gPlayerNum].cam.eye;
        for (s32 patch=0;patch<terrain->patchCount;patch++) {
            StationTerrainPatch* surface=&terrain->patches[patch];
            if (kind==0) {
                f32 dx=eye.x-surface->center.x, dy=eye.y-surface->center.y;
                f32 sn=SIN_DEG(surface->angle), cs=COS_DEG(surface->angle);
                f32 across=fmaxf(0,fabsf(dx*cs+dy*sn)-surface->width);
                f32 along=fmaxf(0,fabsf(eye.z-surface->center.z)-surface->length);
                f32 normal=-dx*sn+dy*cs;
                f32 distance=sqrtf(SQ(across)+SQ(along)+SQ(normal));
                f32 detail=fminf(1,fmaxf(0,(6800-distance)/4000));
                detail=detail*detail*(3-2*detail);
                gDPPipeSync(gMasterDisp++);
                gDPSetPrimColor(gMasterDisp++,0,(s32)(255*detail),255,255,255,255);
            }
            gSPDisplayList(gMasterDisp++,&terrain->commands[surface->command]);
        }
    }
    for (s32 i=0;i<sStationTreeCount;i++) {
        StationTree* tree = &sStationTrees[i];
        FrameInterpolation_RecordOpenChild(tree,0);
        Matrix_Push(&gGfxMatrix);
        Matrix_Translate(gGfxMatrix,tree->pos.x,tree->pos.y,tree->pos.z,MTXF_APPLY);
        Matrix_RotateZ(gGfxMatrix,tree->angle*M_DTOR,MTXF_APPLY);
        Vec3f camera = gPlayer[gPlayerNum].cam.eye;
        f32 tangent = (camera.x-tree->pos.x)*COS_DEG(tree->angle)+(camera.y-tree->pos.y)*SIN_DEG(tree->angle);
        Matrix_RotateY(gGfxMatrix,Math_Atan2F(tangent,camera.z-tree->pos.z),MTXF_APPLY);
        Matrix_Scale(gGfxMatrix,tree->scale,tree->scale,tree->scale,MTXF_APPLY);
        Matrix_SetGfxMtx(&gMasterDisp);
        RCP_SetupDL_60(gFogRed,gFogGreen,gFogBlue,gFogAlpha,gFogNear,gFogFar);
        gSPClearGeometryMode(gMasterDisp++,G_CULL_BACK);
        gSPDisplayList(gMasterDisp++,aCoTreeDL);
        Matrix_Pop(&gGfxMatrix);
        FrameInterpolation_RecordCloseChild();
    }
    Matrix_Translate(gGfxMatrix, 0, 0, BOLSE_INTERIOR_ENTRY_Z, MTXF_APPLY);
    Matrix_Scale(gGfxMatrix, BOLSE_INTERIOR_ENTRY_SCALE, BOLSE_INTERIOR_ENTRY_SCALE, BOLSE_INTERIOR_ENTRY_SCALE, MTXF_APPLY);
    Matrix_SetGfxMtx(&gMasterDisp);
    RCP_SetupDL(&gMasterDisp, SETUPDL_29);
    gSPClearGeometryMode(gMasterDisp++, G_CULL_BACK);
    gSPDisplayList(gMasterDisp++, aAndPathEntranceDL);
    Matrix_Pop(&gGfxMatrix);
    FrameInterpolation_RecordCloseChild();
}


bool BolseInterior_Active(void) {
    return gCurrentLevel==LEVEL_VERSUS && gVersusStage==VS_STAGE_BOLSE_INTERIOR;
}
int BolseInterior_VertexCount(void) {return sStationReady?sStationVertexCount:0;}
void BolseInterior_Load(void) {
    Bolse_StationDockingLoad();
    Bolse_StationBuild();
    gGroundHeight=-25000.0f;
    gDrawGround=true;gDrawBackdrop=0;gStarCount=0;
    gProjectFar=40000;
    gFogRed=18;gFogGreen=26;gFogBlue=35;gFogAlpha=255;
    gFogNear=BOLSE_INTERIOR_FOG_NEAR;gFogFar=BOLSE_INTERIOR_FOG_FAR;
    gLight1R=220;gLight1G=225;gLight1B=235;
    gLight2R=70;gLight2G=88;gLight2B=115;
    gAmbientR=40;gAmbientG=48;gAmbientB=62;
}
void BolseInterior_SetupPlayer(Player* player) {
    static const Vec3f starts[4]={{-2400,0,-3500},{2400,0,-8500},{2400,1200,-3500},{-2400,-1200,-8500}};
    player->num=gPlayerNum;
    player->pos=starts[player->num];player->trueZpos=player->pos.z;
    player->rot=(Vec3f){0,0,0};
    player->yRot_114=player->num%2?180:0;player->xRot_120=player->aerobaticPitch=0;
    player->bankAngle=player->zRotBank=player->zRotBarrelRoll=player->camRoll=0;
    player->pathFloor=-BOLSE_INTERIOR_RADIUS+300;player->pathHeight=BOLSE_INTERIOR_RADIUS-300;
    player->hideShadow=true;player->state=PLAYERSTATE_ACTIVE;
}
void BolseInterior_Constrain(Player* player) {
    Vec3f previous={player->pos.x-player->vel.x,player->pos.y-player->vel.y,player->pos.z-player->vel.z};
    bool hit=Bolse_StationClamp(&player->pos.z,BOLSE_INTERIOR_BACK+100,BOLSE_INTERIOR_FRONT-100);
    hit|=Bolse_StationResolve(&player->pos,previous,BOLSE_INTERIOR_CLEARANCE);
    if(hit && player->hitTimer==0)Player_ApplyDamage(player,0,5);
}
bool BolseInterior_ShotImpact(PlayerShot* shot) {
    if(!BolseInterior_Active() || (shot->obj.id==PLAYERSHOT_BOMB && shot->unk_5C!=0))return false;
    Vec3f start={shot->obj.pos.x-shot->vel.x,shot->obj.pos.y-shot->vel.y,shot->obj.pos.z-shot->vel.z};
    Vec3f previous=start;
    float distance=sqrtf(SQ(shot->vel.x)+SQ(shot->vel.y)+SQ(shot->vel.z));
    int count=(int)ceilf(distance/25.0f);if(count<1)count=1;
    for(int step=1;step<=count;step++){
        float t=(float)step/count;
        Vec3f p={start.x+shot->vel.x*t,start.y+shot->vel.y*t,start.z+shot->vel.z*t};
        if(p.z>=BOLSE_INTERIOR_FRONT||p.z<=BOLSE_INTERIOR_BACK||Bolse_StationResolve(&p,previous,25)){
            shot->obj.pos=p;return true;
        }
        previous=p;
    }
    return false;
}
void BolseInterior_ItemPosition(int index,Vec3f* position) {
    static const Vec3f points[5]={{0,0,-5000},{-3000,1000,-8000},{3000,-1000,-8000},{0,3000,-10000},{0,-3000,-2000}};
    *position=points[index%5];
}
